    private GeneralAssetManager() {
    }

    private static GeneralAsset asset(String id, String chineseName, String kingdom, String category) {
        if (!id.matches("[a-z0-9_]+")) {
            throw new IllegalArgumentException("Unsafe general id: " + id);
        }
        return new GeneralAsset(id, chineseName, kingdom, category, new ResourceLocation("sanguosha", "textures/item/general/" + id + ".png"));
    }

    public static int reload() {
        return ASSETS.size();
    }

    public static List<GeneralAsset> assets() {
        return ASSETS;
    }

    public static List<GeneralAsset> assets(String category) {
        return ASSETS.stream().filter(asset -> asset.category().equals(category)).toList();
    }

    public static Optional<GeneralAsset> get(String id) {
        return ASSETS.stream().filter(asset -> asset.id().equals(id)).findFirst();
    }

    public static boolean contains(String id) {
        return GeneralAssetManager.get(id).isPresent();
    }

    public record GeneralAsset(String id, String chineseName, String kingdom, String category, ResourceLocation texture) {
    }
